import { TrendingDownIcon, TrendingUpIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

export interface StatWidgetProps {
  label: string
  value: string
  /** Change since the previous period, e.g. "+20.1%". */
  delta?: string
  trend?: "up" | "down" | "flat"
  /** Small note under the value, e.g. "vs. last month". */
  hint?: string
  className?: string
}

/**
 * A single headline number.
 *
 * Every colour here comes from a theme token, so the widget follows the host
 * app's palette and dark mode with no `dark:` overrides of its own.
 */
export function StatWidget({
  label,
  value,
  delta,
  trend = "flat",
  hint,
  className,
}: StatWidgetProps) {
  const TrendIcon = trend === "up" ? TrendingUpIcon : trend === "down" ? TrendingDownIcon : null

  return (
    <div className={cn("flex h-full flex-col justify-center gap-1", className)}>
      <span className="text-muted-foreground text-xs font-medium tracking-wide uppercase">
        {label}
      </span>
      <div className="flex flex-wrap items-baseline gap-2">
        <span className="text-2xl font-semibold tabular-nums">{value}</span>
        {delta && (
          <Badge variant={trend === "down" ? "destructive" : "secondary"}>
            {TrendIcon && <TrendIcon data-icon="inline-start" />}
            {delta}
          </Badge>
        )}
      </div>
      {hint && <span className="text-muted-foreground text-xs">{hint}</span>}
    </div>
  )
}

/**
 * Miniature for the add-widget bar.
 *
 * Purpose-built rather than a scaled-down `StatWidget`: at 80px tall the real
 * type scale is unreadable, and a CSS transform would blur it.
 */
export function StatWidgetPreview() {
  return (
    <div className="flex h-full flex-col justify-center gap-1">
      <span className="bg-muted-foreground/25 h-1.5 w-10 rounded-full" />
      <div className="flex items-baseline gap-1.5">
        <span className="text-base leading-none font-semibold tabular-nums">$45.2k</span>
        <Badge variant="secondary" className="px-1 py-0 text-[9px] leading-4">
          <TrendingUpIcon data-icon="inline-start" />
          20%
        </Badge>
      </div>
      <span className="bg-muted-foreground/15 h-1 w-14 rounded-full" />
    </div>
  )
}

import { cn } from "@/lib/utils"
import { Progress } from "@/components/ui/progress"

export interface ProgressWidgetRow {
  label: string
  value: number
  max?: number
  /** Optional right-hand caption. Defaults to a percentage. */
  caption?: string
}

export interface ProgressWidgetProps {
  rows: ProgressWidgetRow[]
  className?: string
}

/** A stack of labelled progress bars — quotas, goals, capacity. */
export function ProgressWidget({ rows, className }: ProgressWidgetProps) {
  return (
    <div className={cn("flex h-full flex-col justify-center gap-3", className)}>
      {rows.map((row) => {
        const max = row.max ?? 100
        const percent = max === 0 ? 0 : Math.round((row.value / max) * 100)
        return (
          <div key={row.label} className="flex flex-col gap-1.5">
            <div className="flex items-baseline justify-between gap-2">
              <span className="truncate text-sm font-medium">{row.label}</span>
              <span className="text-muted-foreground text-xs tabular-nums">
                {row.caption ?? `${percent}%`}
              </span>
            </div>
            <Progress value={percent} aria-label={`${row.label}: ${percent}%`} />
          </div>
        )
      })}
    </div>
  )
}

const PREVIEW_ROWS = [
  { fill: "72%", label: "w-10" },
  { fill: "45%", label: "w-8" },
  { fill: "88%", label: "w-12" },
]

/**
 * Miniature for the add-widget bar. The bars fill as the bar opens, staggered,
 * then rest at their real values — so it still reads as progress at rest.
 */
export function ProgressWidgetPreview() {
  return (
    <div className="flex h-full flex-col justify-center gap-2">
      {PREVIEW_ROWS.map((row, index) => (
        <div key={row.fill} className="flex flex-col gap-1">
          <span className={cn("bg-muted-foreground/25 h-1 rounded-full", row.label)} />
          <span className="bg-muted h-1.5 overflow-hidden rounded-full">
            <span
              className="bg-primary block h-full origin-left rounded-full motion-safe:[animation:dashboard-fill-x_520ms_cubic-bezier(0.2,0,0,1)_backwards]"
              style={{ width: row.fill, animationDelay: `${index * 80}ms` }}
            />
          </span>
        </div>
      ))}
    </div>
  )
}

"use client"

import { Area, AreaChart, Bar, BarChart, CartesianGrid, XAxis } from "recharts"

import { cn } from "@/lib/utils"
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"

export interface ChartWidgetProps {
  data: { label: string; value: number }[]
  /** Legend/tooltip name for the series. */
  seriesName?: string
  variant?: "bar" | "area"
  /** Any chart token, e.g. "var(--chart-1)". */
  color?: string
  className?: string
}

/**
 * A compact chart sized to fill its grid cell.
 *
 * `ChartContainer` defaults to `aspect-video`; a dashboard widget has a height
 * fixed by the grid instead, so we swap in `aspect-auto` and fill the cell.
 *
 * Animation is off deliberately. The grid re-measures on resize, and replaying
 * a grow-from-zero intro on every measure both looks broken and can leave bars
 * stranded at zero height if measures arrive faster than the animation.
 */
export function ChartWidget({
  data,
  seriesName = "Value",
  variant = "bar",
  color = "var(--chart-1)",
  className,
}: ChartWidgetProps) {
  const config = {
    value: { label: seriesName, color },
  } satisfies ChartConfig

  const axis = (
    <>
      <CartesianGrid vertical={false} />
      <XAxis
        dataKey="label"
        tickLine={false}
        axisLine={false}
        tickMargin={8}
        minTickGap={8}
      />
      <ChartTooltip content={<ChartTooltipContent />} />
    </>
  )

  return (
    <ChartContainer
      config={config}
      className={cn("aspect-auto h-full w-full", className)}
    >
      {variant === "area" ? (
        <AreaChart data={data} margin={{ left: 4, right: 4, top: 4 }}>
          {axis}
          <Area
            dataKey="value"
            type="natural"
            stroke="var(--color-value)"
            fill="var(--color-value)"
            fillOpacity={0.2}
            strokeWidth={2}
            isAnimationActive={false}
          />
        </AreaChart>
      ) : (
        <BarChart data={data} margin={{ left: 4, right: 4, top: 4 }}>
          {axis}
          <Bar dataKey="value" fill="var(--color-value)" radius={4} isAnimationActive={false} />
        </BarChart>
      )}
    </ChartContainer>
  )
}

const PREVIEW_BARS = [45, 80, 60, 95, 70]

/**
 * Miniature for the add-widget bar.
 *
 * Plain CSS bars rather than a real chart: recharts would mount a
 * ResponsiveContainer and its own resize observer for every palette entry,
 * which is a lot of machinery for an 80px thumbnail.
 *
 * The bars grow up as the bar opens, staggered, then rest at their real heights
 * — so it reads as a chart even after the animation finishes. `scaleY` keeps the
 * work on the compositor; animating `height` would relayout every frame.
 */
export function ChartWidgetPreview() {
  return (
    <div className="flex h-full items-end gap-1">
      {PREVIEW_BARS.map((height, index) => (
        <span
          key={index}
          // Uses the same chart token as the real widget, so the miniature is
          // an honest preview of what gets placed.
          className="flex-1 origin-bottom rounded-sm bg-[var(--chart-1)] opacity-80 motion-safe:[animation:dashboard-grow-y_460ms_cubic-bezier(0.2,0,0,1)_backwards]"
          style={{ height: `${height}%`, animationDelay: `${index * 55}ms` }}
        />
      ))}
    </div>
  )
}

import { cn } from "@/lib/utils"

export interface NotesWidgetProps {
  /**
   * Rendered prose. Pass a markdown renderer's output, streamed assistant
   * output, or plain JSX — Typeset styles the resulting elements either way.
   */
  children: React.ReactNode
  className?: string
}

/**
 * A prose widget styled by Typeset.
 *
 * Text-heavy widgets are where a dashboard usually falls apart: headings and
 * lists arrive unstyled because the surrounding app resets them, so every
 * project re-styles the same elements by hand. Typeset handles all of it from
 * one CSS file, driven by three custom properties.
 *
 * `typeset-widget` tightens the rhythm for a small grid cell. It is defined in
 * the dashboard theme CSS; adjust it there, or override inline:
 *
 *     <NotesWidget className="[--typeset-flow:1.5em]">…</NotesWidget>
 */
export function NotesWidget({ children, className }: NotesWidgetProps) {
  return (
    <div className={cn("typeset typeset-widget h-full overflow-auto", className)}>
      {children}
    </div>
  )
}

const PREVIEW_LINES = ["w-full", "w-[85%]", "w-[92%]", "w-[60%]"]

/**
 * Miniature for the add-widget bar: a heading and a few lines of prose, fading
 * in line by line as the bar opens.
 */
export function NotesWidgetPreview() {
  return (
    <div className="flex h-full flex-col gap-1.5">
      <span className="bg-foreground/60 h-1.5 w-12 rounded-full motion-safe:animate-in motion-safe:fade-in motion-safe:duration-300" />
      {PREVIEW_LINES.map((width, index) => (
        <span
          key={width}
          className={cn(
            "bg-muted-foreground/25 h-1 rounded-full",
            "motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-left-1",
            "motion-safe:fill-mode-backwards motion-safe:duration-300",
            width
          )}
          style={{ animationDelay: `${60 + index * 55}ms` }}
        />
      ))}
    </div>
  )
}
